//三优无错
if(baseUrl.match(/333uu/)){
[["深空彼岸",0,1],["深空彼岸",1,1],["宇宙职业选手",0,6],["灵境行者",0,7],["不科学御兽",0,177],["光阴之外",0,178],["明克街13号",0,213],["我的属性修行人生",0,273],["神秘复苏",0,315],["夜的命名术",0,346],["仙者",0,367],["万相之王",1,4],["轮回乐园",1,5],["弃宇宙",1,6],["深海余烬",1,149],["机武风暴",1,150],["唐人的餐桌",1,180],["诸界第一因",1,247],["择日飞升",1,248],["这游戏也太真实了",1,302],["7号基地",1,303],["我就是神",1,304],["人道大圣",1,305]].map(a=>$(a[0],a[1],'https://www.'+u[a[1]]+'/?cat='+a[2]));
}
else{
html=org.jsoup.Jsoup.parse(result)

//云中歌
if(baseUrl.match(/yunzhongge/)){
$(java.getString('h1@text'),2,baseUrl);
html.select(".links-body a").forEach(a=>$(a.text(),2,a.attr("href")));
}


//乡村小说
else if(baseUrl.match(/xiangcun2018/)){
html.select(".bk").forEach(h=>json.push({
			name: h.select("h3 a").text(),
			new: h.select(".booknews a").text(),
			kind: String(h.select("p").text()).replace(/^\s*简介.\s*(《[^》]+》是?)?/,''),
			img: h.select("img").attr("src"),
			bookUrl: h.select("h3 a").attr("href")
	}));
}
}
json

ruleToc.chapterList:
article||.booklist@span||.book_list@a
@js:
list=[]
$=result
function $$($){
		return list.push(JSON.stringify($))
	}


//云中歌&&乡村小说
if(baseUrl.match(/yunzhongge|xiangcun2018/)){for(i in $){
if(/^\s*$/.test(String(a=$[i].select('a'))))
		$$({text:$[i].text(),volume:true});
else
		$$({text:a.text(),href:a.attr('href')});
	}}


//三优无错
else if(baseUrl.match(/333uu|wcxs5/)){
	for(i in $){
		a=$[i].select('.a-link')
		text=a.text()
		href=a.attr('href')
		a=$[i].select('.float-right span').text()
		b=$[i].select('p').text()
		info='⏱️ '+a+'　📑 '+b
		$$({text:text,href:href,info:info})
		}
	}
list

